-- GENERATED by `wfi generate` from data/quest/quest-0008.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [8080] = { nil, "Vinci la battaglia per l'Arathi Basin, ottieni un Arathi Basin Mark of Honor e riportalo al Sergeant Maclear a Refuge Pointe.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. E ti diranno anche che una battaglia combattuta con equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!\n\nEcco perché l'Arathi Basin è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e tutti si possono ottenere lì.\n\nEcco cosa voglio da te, {name}. Entra nell'Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con un Mark of Honor.", "Hai i Marks of Honor, {name}? La League of Arathor non può combattere una battaglia decente senza...", "Hai il Mark! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle rapidamente alle truppe.\n\nGrazie, {name}. In effetti, è portando a termine missioni come la tua che si vincono davvero le guerre.", nil, 0x9a052c21, 0x52039791, 0x37247045, 0x2c6df8ea, "m...." },
  [8105] = { "La battaglia per l'Arathi Basin!", "Assalta la miniera, la segheria, la forgia e la fattoria, poi torna dal Field Marshal Oslight a Refuge Pointe.", "{name}, la battaglia per l'Arathi Basin è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e gestiti per rifornire le nostre forze di materie prime e provviste indispensabili. Ti incarico di assaltare i punti più lontani dalla nostra base nell'Arathi Basin.\n\nAssalta la fattoria, la miniera, la segheria e la forgia quando sono controllate dal nemico. Trova lo stendardo nemico e strappalo dall'asta!\n\nQuando l'avrai fatto con tutti e quattro i punti, torna da me.", "{name}, non hai ancora assaltato le quattro basi. Torna da me quando avrai completato i tuoi obiettivi.", "Ho ricevuto rapporti sulle tue imprese nell'Arathi Basin, {name}. Ben fatto! Con persone come te che si uniscono alla lotta qui, ho fiducia che un giorno riconquisteremo le nostre terre.", 0xe8197bb2, 0x24235866, 0xc4127755, 0x735eaefc, 0x82cf24dd, "....." },
  [8114] = { "Controlla quattro basi", "Entra nell'Arathi Basin, conquista e controlla quattro basi contemporaneamente, poi torna dal Field Marshal Oslight a Refuge Pointe.", "{name}, hai portato la battaglia dell'Arathi Basin ai nostri nemici e ti sei <guadagnato/guadagnata> grandi onori su quel campo di battaglia. Ci hai dimostrato il tuo valore come {class}, e hai dimostrato ai nostri nemici che non ci piegheremo alla loro malvagità!\n\nVisto il valore che hai dimostrato, ho un compito difficile per te. Voglio che conquisti e tenga almeno quattro basi nell'Arathi Basin. Se ci riesci, non solo ci assicureremo risorse cruciali, ma mostreremo all'Orda il nostro predominio!\n\nVa', {name}, e buona fortuna.", nil, "Ottimo lavoro, {name}! Un esploratore entusiasta mi ha portato un rapporto sulle tue imprese. Noi della League of Arathor siamo molto soddisfatti!\n\nStai rapidamente diventando un eroe locale tra i soldati della lega, e l'impresa di oggi conferma ancora una volta la tua splendida reputazione.", 0xc98ab4c9, 0xd307226a, 0xc7be4a3a, nil, 0x9427c6fc, "...m." },
  [8115] = { "Controlla cinque basi", "Controlla $N1 basi nell'Arathi Basin contemporaneamente, poi torna dal Field Marshal Oslight a Refuge Pointe.", "{name}, combattere per le risorse dell'Arathi Basin è un'impresa sanguinosa. I tuoi servigi alla League of Arathor sono tanto necessari quanto apprezzati.\n\nE abbiamo un ultimo compito per te.\n\nLa lega vuole lanciare un'offensiva decisa contro l'occupazione dell'Arathi Basin da parte dei Defilers. Vogliamo che vengano cacciati da ogni punto strategico del campo di battaglia!\n\nNon sarà facile, ma se c'è qualcuno che può riuscirci, sei tu.", nil, nil, 0x5965ad2a, 0x6c8e0a40, 0xecee114f, nil, nil, "...mm" },
  [8120] = { "La battaglia per l'Arathi Basin!", nil, nil, nil, nil, 0xe8197bb2, nil, nil, nil, nil, ".mmmm" },
  [8149] = { "Onorare un eroe", "Recati all'Uther's Tomb, nelle Western Plaguelands, e usa l'Uther's Tribute presso la sua statua, poi torna da Wagner Hammerstrike, fuori Ironforge, prima che finisca l'Harvest Festival.", "Durante l'Harvest Festival di Azeroth rendiamo grazie agli eroi per i sacrifici, in alcuni casi il sacrificio supremo, che hanno compiuto per noi. L'Alliance riconosce molti eroi, ma nessuno ha una storia più tragica di quella di Uther Lightbringer.\n\nAiutaci a onorare Uther portando questa offerta alla sua tomba, nelle Western Plaguelands. Ponila presso la sua statua, poi torna da me. Resterò qui solo fino alla fine della festa, quindi non perdere tempo a rendere omaggio a Uther.", "Hai fatto il viaggio fino all'Uther's Tomb e vi hai deposto l'offerta?\n\nPuò essere un viaggio pericoloso per gli avventurieri meno esperti; un modo più sicuro, relativamente parlando, per arrivarci potrebbe essere risalire verso nord, nelle Plaguelands, dal fiume che attraversa Hillsbrad. Nasce da un lago adiacente a Sorrow Hill; procedi verso ovest su per le colline, tenendoti alla larga dalla tomba vicina... una tomba infestata dalla Scourge.", "Era un eroe tra gli eroi, Uther. Non riesco nemmeno a immaginare l'angoscia che provò quando Arthas, il suo allievo migliore e qualcuno che Uther amava come un figlio, tradì l'intera umanità. Eppure si levò per cercare di fermare Arthas, e per questo sarà ricordato per sempre come un vero paladino. La sua lotta durò fino alla fine, pensando solo a coloro che poteva salvare.\n\nGrazie, {name}. Oggi hai reso omaggio a un grande eroe, onorando il suo spirito e lo spirito dell'Harvest Festival.", 0x9e2b2607, 0x95fd1a45, 0xdb133806, 0x7489d4e8, 0x391a64b5, "....." },
  [8150] = { "Onorare un eroe", nil, nil, nil, nil, 0x9e2b2607, nil, nil, nil, nil, ".mmmm" },
  [8154] = { "Risorse dell'Arathi Basin!", "Vinci la battaglia per l'Arathi Basin, ottieni un'Arathi Resource Crate e riportala al Sergeant Maclear a Refuge Pointe.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. E ti diranno anche che una battaglia combattuta con equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!\n\nEcco perché l'Arathi Basin è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e tutti si possono ottenere lì.\n\nEcco cosa voglio da te, {name}. Entra nell'Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con una cassa di risorse.", "Hai i Marks of Honor, {name}? La League of Arathor non può combattere una battaglia decente senza...", "Hai il Mark! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle rapidamente alle truppe.\n\nGrazie, {name}. In effetti, è portando a termine missioni come la tua che si vincono davvero le guerre.", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
