  [8171] = { "La battaglia per l'Arathi Basin!", nil, nil, nil, nil, 0xe8197bb2, nil, nil, nil, nil, ".mmmm" },
  [8234] = { nil, "Recupera la Sealed Azure Bag dal Timbermaw Shaman ad Azshara. Poi porta la borsa all'Archmage Xylem, anche lui ad Azshara.", "Prima le cose importanti. Ciò che ho perso è una piccola borsa blu, il cui contenuto è una faccenda privata.\n\nNon perdere tempo a inseguire i ladri, perché sono già morti. Quello che sappiamo è che quegli sciocchi non sono riusciti ad aprire la borsa, quindi l'hanno venduta a qualche sciamano timbermaw ad Azshara come reliquia sacra. Astuto.\n\nHo bisogno che tu vada ad Azshara e la recuperi dallo sciamano con astuzia... o con la forza. Scommetto che avrai più fortuna con il primo metodo. Una volta ottenuta, portala all'Archmage Xylem.", "Ci conosciamo?", "Vedo che hai la borsa di Lord Ravenholdt. Perché non l'hai detto subito, <ragazzo/ragazza>?", nil, 0x0ea5890f, 0xfe836e00, 0x879570ca, 0x860f19ff, "m....", nil, nil, nil, nil, 0xf0af4ecb },
  [8249] = { "Servono scrigni", nil, nil, "I miei ladri devono affinare le loro capacità di scassinatori, e mi servono serrature di difficoltà adeguata: la roba che ci fa Zan va bene solo per i novellini più sprovveduti.\n\nFacciamo così: se mi porti 5 Heavy Junkboxes, ti darò alcuni dei migliori coltelli da lancio conosciuti dalla stirpe dei ladri.\n\nPuoi aprire gli scrigni e frugarci dentro, ma dovrai lasciarci almeno qualche moneta... anche un ladro in addestramento ha bisogno di motivazione.", "Che questi coltelli trovino posto nel cuore di qualcuno.\n\nLetteralmente.", 0x26effe33, nil, nil, 0x8ade345a, 0x5400bb60, ".mm.." },
  [8250] = { "L'arte della magia", "Cerca Sanath Lim-yo e ottieni il passaggio per vedere l'Archmage Xylem.", "L'Archmage Xylem ultimamente va chiedendo in giro... di qualcuno con la tua esperienza.\n\nSe vuoi cercarlo, lo troverai ad Azshara. La sua torre è costruita in alto sulle scogliere, e l'unico modo per salirci è un incantesimo di teletrasporto lanciato dal suo arrogante servitore, Sanath Lim-yo.\n\nSanath si accampa sotto la torre del suo padrone. Per trovarlo, vai dove la strada principale di Azshara si biforca all'ingresso delle Ruins of Eldarath. Da lì, dirigiti <dritto/dritta> a nord finché non raggiungi le scogliere.", nil, "<Sanath ti guarda con un ghigno.>\n\nL'Arch{class} Xylem attende il tuo arrivo.", 0x63df1028, 0xe163bc1a, 0xddf08947, nil, 0x6e8ed03a, "...m." },
  [8254] = { "Aiuto per i Cenarion", "Cerca Ogtinc ad Azshara.", "È nella natura del divino aiutare chi è nel bisogno. Il come è irrilevante: conta solo il perché.\n\nIl Cenarion Circle ha proprio un bisogno simile. Parla con Ogtinc per aiutarli nella loro difficoltà. Risiede in cima alle scogliere a nord-est delle Ruins of Eldarath, ad Azshara.", nil, "Il tuo arrivo mi ha tolto un peso dalle spalle. Abbiamo molto da fare.", 0x4f3b88f6, 0xc18aa317, 0xcabd114b, nil, 0x4d19dd02, "...m." },
  [8260] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrare il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo nell'Arathi Basin.\n\nContinuando a dimostrare il tuo valore nel bacino, scoprirai che questi oggetti diventeranno disponibili per l'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x837511ae, "mmmm." },
  [8261] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrare il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo nell'Arathi Basin.\n\nContinuando a dimostrare il tuo valore nel bacino, scoprirai che questi oggetti diventeranno disponibili per l'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x837511ae, "mmmm." },
  [8262] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrare il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo nell'Arathi Basin.\n\nContinuando a dimostrare il tuo valore nel bacino, scoprirai che questi oggetti diventeranno disponibili per l'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x837511ae, "mmmm." },
  [8263] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrare il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo nell'Arathi Basin.\n\nContinuando a dimostrare il tuo valore nel bacino, scoprirai che questi oggetti diventeranno disponibili per l'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x837511ae, "mmmm." },
  [8264] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrare il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo nell'Arathi Basin.\n\nContinuando a dimostrare il tuo valore nel bacino, scoprirai che questi oggetti diventeranno disponibili per l'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x837511ae, "mmmm." },
  [8266] = { "Nastri del sacrificio", nil, nil, "Capisco che a volte possa essere difficile avere la meglio a Warsong Gulch. Eppure il tuo impegno per noi, anche quando non arriva la vittoria, è importante.\n\nSe completi una delle prove a Warsong Gulch senza ottenere la vittoria, riceverai comunque un Ribbons of Sacrifice. Portamelo, così le Sentinels potranno ricompensarti per aver agito in nostro favore... anche se questa volta non sei <riuscito/riuscita> a vincere.", "Beh, non sei <fuggito/fuggita> davanti alla sconfitta. Hai tenuto la tua posizione, {name}, ed è questo, in fondo, che fa <un/una> <vero/vera> <eroe/eroina>. Senza dubbio vincerai la prossima volta... ma intanto ti ringraziamo per il tuo impegno.", 0x8ea61f00, nil, nil, 0xe9324b2e, 0xc338822b, ".mm.." },
  [8268] = { "Nastri del sacrificio", nil, nil, nil, "Beh, non sei <fuggito/fuggita> davanti alla sconfitta. Hai tenuto la tua posizione, {name}, ed è questo, in fondo, che fa <un/una> <vero/vera> <eroe/eroina>. Senza dubbio vincerai la prossima volta... ma intanto ti ringraziamo per il tuo impegno.", 0x8ea61f00, nil, nil, nil, 0xc338822b, ".mmm." },
  [8271] = { "Eroe degli Stormpike", nil, nil, nil, "Come eroe degli Stormpike, puoi scegliere un oggetto tra questi tesori appena saccheg... ehm, recuperati.", 0x29b1fe38, nil, nil, nil, 0x32d06266, ".mmm." },
  [8275] = { "Riconquistare Silithus", "Parla con il Windcaller Proudhorn a Cenarion Hold, a Silithus.", "Attenzione, eroi dell'Alleanza! La minaccia silitide è stata lasciata senza controllo troppo a lungo. Senza alcuna vera opposizione, si sono preparati per tutto questo tempo a un'espansione su larga scala.\n\nLe forze del Cenarion Circle si stanno radunando a Silithus per portare la lotta a queste creature miserabili, e tutti gli avventurieri abili sono chiamati a unirsi a noi!\n\nNon aspettate che sia troppo tardi! Aiutateci a difendere Azeroth! Presentatevi al Windcaller Proudhorn a Cenarion Hold per istruzioni precise!", nil, "Eccellente, una nuova recluta che risponde alla chiamata alle armi contro i silitidi. <Benvenuto/Benvenuta> a Cenarion Hold, {class}. Sono lieto di vedere che le parole dei nostri emissari raggiungono eroi del tuo calibro. Non ti mancheranno le occasioni per aiutarci nei nostri sforzi qui, e mi aspetto che dimostrerai presto di essere un prezioso alleato per la nostra causa.", 0x1f4019a6, 0xdd40063b, 0x86d6a1fd, nil, 0xe3b065a1, "...m." },
  [8276] = { "Riconquistare Silithus", "Parla con il Windcaller Proudhorn a Cenarion Hold, a Silithus.", nil, nil, "Eccellente, una nuova recluta che risponde alla chiamata alle armi contro i silitidi. <Benvenuto/Benvenuta> a Cenarion Hold, {class}. Sono lieto di vedere che le parole dei nostri emissari raggiungono eroi del tuo calibro. Non ti mancheranno le occasioni per aiutarci nei nostri sforzi qui, e mi aspetto che dimostrerai presto di essere un prezioso alleato per la nostra causa.", 0x1f4019a6, 0xdd40063b, nil, nil, 0xe3b065a1, "..mm." },
  [8290] = { nil, "Entra a Warsong Gulch e sconfiggi l'Horde, ottieni un Warsong Gulch Mark of Honor e torna dalla Sentinel Farsong, al Silverwing Grove.", "Oltre questa galleria troverai un campo di conflitto e tumulto, giovane {class}. L'Horde continua a devastare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra a Warsong Gulch e difendi Silverwing Hold. Respingi le forze d'invasione dell'Horde!\n\nFallo e guadagnerai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", nil, nil, nil, 0xfeb46d9a, 0xd5134582, nil, nil, "m..mm" },
  [8291] = { "Sconfiggi gli invasori!", "Entra a Warsong Gulch e sconfiggi l'Horde, ottieni un Silverwing Talisman of Merit e torna dalla Sentinel Farsong, al Silverwing Grove.", "Oltre questa galleria troverai un campo di conflitto e tumulto, giovane {class}. L'Horde continua a devastare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra a Warsong Gulch e difendi Silverwing Hold. Respingi le forze d'invasione dell'Horde!\n\nFallo e guadagnerai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto a Warsong Gulch e difeso Silverwing Hold?", "Hai dimostrato il tuo valore nei nostri sforzi a Warsong Gulch. Continua ad aiutare la causa e portami altri Marks of Honor. Fallo, e guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xbdddd230, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [8297] = { "Risorse dell'Arathi Basin!", "Vinci la battaglia per l'Arathi Basin, ottieni un'Arathi Resource Crate e riportala al Sergeant Maclear a Refuge Pointe.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. E ti diranno anche che una battaglia combattuta con equipaggiamento scadente o a stomaco vuoto è persa prima ancora di cominciare!\n\nEcco perché l'Arathi Basin è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e tutti si possono ottenere lì.\n\nEcco cosa voglio da te, {name}. Entra nell'Arathi Basin, vinci la battaglia tenendo più basi del nemico e torna da me con una cassa di risorse.", "Hai i Marks of Honor, {name}? La League of Arathor non può combattere una battaglia decente senza...", "Hai il Mark! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle rapidamente alle truppe.\n\nGrazie, {name}. In effetti, è portando a termine missioni come la tua che si vincono davvero le guerre.", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8308] = { nil, nil, nil, "Oh, povera me.", nil, nil, nil, nil, 0x9e26ead5, nil, "mmm.m" },
  [8311] = { "Dolcetti dell'Hallow's End per Jesper!", "Parla con i locandieri di Stormwind, Ironforge e Darnassus, e anche con Talvash del Kissel a Ironforge. Esegui i trucchi che ti chiedono in cambio dei dolcetti che offrono.\n\nTorna da Jesper, allo Stormwind Orphanage, con un Darnassus Marzipan, un Gnomeregan Gumdrop, uno Stormwind Nougat e un Ironforge Mint.", "Voglio andare a fare dolcetto o scherzetto, ma non posso perché sono malato. Se ci vai tu per me, ti scambierò le caramelle che prendi con alcune che ho già! Credo che queste caramelle ti piaceranno: ti trasformano in cose buffe e spaventose!\n\nOgni locandiere delle grandi città ha caramelle da regalare per l'Hallow's End: parla con loro e fai gli scherzetti che ti chiedono! E anche un piccolo gnomo di nome Talvash, a Ironforge, distribuisce caramelle. Quando avrai tutte le caramelle, riportamele qui!", "Hai finito di fare dolcetto o scherzetto? Sono triste di non poterci andare perché sono malato, ma il tuo aiuto mi fa sentire un po' meglio...", "Wow, le hai prese tutte! Sei <fantastico/fantastica>!\n\nGrazie per aver fatto dolcetto o scherzetto per me. Ecco, prendi questi dolcetti alla zucca: credo che ti piaceranno tantissimo!\n\nBuon Hallow's End, {name}!", 0x52c1029c, 0xf583861b, 0x4f387161, 0xee372d69, 0xc67a4faf, "....." },
  [8312] = { nil, nil, nil, "Hai finito di fare dolcetto o scherzetto? Sono triste di non poterci andare perché sono malato, ma il tuo aiuto mi fa sentire un po' meglio...", "Wow, le hai prese tutte! Sei <fantastico/fantastica>!\n\nGrazie per aver fatto dolcetto o scherzetto per me. Ecco, prendi questi dolcetti alla zucca: credo che ti piaceranno tantissimo!\n\nBuon Hallow's End, {name}!", nil, nil, nil, 0xee372d69, 0xc67a4faf, "mmm.." },
  [8353] = { "Fare la gallina per una mentina", "Fai l'emote della gallina davanti all'Innkeeper Firebrew e in cambio riceverai una Ironforge Mint!", "Ah, dolcetto o scherzetto per un bambino malato, eh? Stavo per dire che sei un po' troppo grande per andare in giro a caccia di caramelle...\n\nBe', per il mio dolcetto, una Ironforge Mint, dovrai... chiocciare come una gallina! Sì, le galline adorano le mentine... va bene, forse non le adorano... ma non ti darò una mentina se non chiocci per me!\n\nAllora, {class}, accetti la sfida o no?! È ora di guadagnarti il tuo dolcetto!", "Sto aspettando...", "Che ridere! Ben fatto, {name}! Ecco il tuo dolcetto.\n\nBuon Hallow's End!", 0x060f03ab, 0x9719c2f8, 0xcd009398, 0x9b13fed7, 0x38c9a3d2, "....." },
  [8354] = { "Fare la gallina per una mentina", nil, nil, "Sto aspettando...", "Che ridere! Ben fatto, {name}! Ecco il tuo dolcetto.\n\nBuon Hallow's End!", 0x060f03ab, nil, nil, 0x9b13fed7, 0x38c9a3d2, ".mm.." },
  [8355] = { "In arrivo una gommosa", "Fai l'emote del treno davanti a Talvash del Kissel e in cambio riceverai una Gnomeregan Gumdrop!", "Uno in giro per dolcetto o scherzetto! Evviva!\n\nBe', anche se stai facendo una cosa nobile raccogliendo caramelle per un bambino malato, non posso lasciarti andare così facilmente. Ho una deliziosa Gnomeregan Gumdrop da dare al bambino malato... se fai il verso del treno per me! Ahah, sì, sarà questo lo scherzetto! Il prezzo di questa gommosa è un verso del treno!\n\nCiuf-ciuf, {class}!", "Be', avanti...", "Tu-tuuu! Ben fatto, {name}! Ecco il tuo dolcetto.\n\nBuon Hallow's End!", 0x62092ab7, 0x42a5e48f, 0x35cb130f, 0xe23a326b, 0x15447c4d, "....." },
  [8356] = { "Muscoli in cambio di Nougat", "Fai l'emote flex davanti all'Innkeeper Allison e in cambio riceverai dello Stormwind Nougat!", "Che costume... interessante che indossi. Anche se sei così gentile da aiutare un bambino malato a fare dolcetto o scherzetto quest'anno, temo di doverti chiedere di farmi uno scherzetto!\n\nVediamo... sembri così forte e <muscoloso/muscolosa> in quel... costume... fammi vedere i muscoli! Sì, forza, mostrami i muscoli, <uomo/donna> <forzuto/forzuta>!\n\nQuando, e solo quando, mi mostrerai i muscoli, ti darò un po' di delizioso Stormwind Nougat. È un ottimo dolcetto dell'Hallow's End.", "Niente caramelle finché non mi mostri i muscoli, {name}...", "Sei proprio potente, ahah! Ben fatto, e grazie per esserti <prestato/prestata> al gioco. Ecco le tue caramelle.\n\nBuon Hallow's End, {name}!", 0x24871022, 0x24c7c11a, 0xb1ed8cc6, 0xca1a781a, 0xff83fd97, ".....", nil, nil, 0x683d7926, nil, nil },
  [8357] = { "Balli in cambio di marzapane", "Fai l'emote del ballo davanti a Innkeeper Saelienne e riceverai in cambio del Darnassus Marzipan!", "Anche se fai dolcetto o scherzetto per un bambino malato, devi comunque fare uno scherzetto per avere il dolcetto! Non possiamo mica cambiare la tradizione, no?\n\nCredo che oggigiorno il prezzo di un pezzo di marzapane sia scatenarsi e ballare! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del gustoso marzapane!", "Sai ballare, vero? Prova così: metti dentro il piede destro... poi il piede destro fuori... il piede destro dentro... e scuoti tutto quanto...", "Sei proprio una macchina da ballo, {name}!\n\nEcco il tuo dolcetto per essere <stato/stata> al gioco. Buon Hallow's End, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.", 0xe471aaf9, 0x8d5f785c, 0x8c369374, 0xf9d6b077, 0x85f6bca9, "....." },
  [8358] = { "In arrivo una gommosa", nil, nil, "Be', avanti...", "Tu-tuuu! Ben fatto, {name}! Ecco il tuo dolcetto.\n\nBuon Hallow's End!", 0x62092ab7, nil, nil, 0xe23a326b, 0x15447c4d, ".mm.." },
  [8359] = { "Muscoli in cambio di Nougat", nil, nil, "Niente caramelle finché non mi mostri i muscoli, {name}...", "Sei proprio potente, ahah! Ben fatto, e grazie per esserti <prestato/prestata> al gioco. Ecco le tue caramelle.\n\nBuon Hallow's End, {name}!", 0x24871022, nil, nil, 0xca1a781a, 0xff83fd97, ".mm.." },
  [8360] = { "Balli in cambio di marzapane", nil, "Anche se fai dolcetto o scherzetto per un bambino malato, devi comunque fare uno scherzetto per avere il dolcetto! Non possiamo mica cambiare la tradizione, no?\n\nCredo che oggigiorno il prezzo di un pezzo di marzapane sia scatenarsi e ballare! Proprio così, fammi vedere come ti muovi! Balla per me e ti darò del gustoso marzapane!", "Sai ballare, vero? Prova così: metti dentro il piede destro... poi il piede destro fuori... il piede destro dentro... e scuoti tutto quanto...", "Sei proprio una macchina da ballo, {name}!\n\nEcco il tuo dolcetto per essere <stato/stata> al gioco. Buon Hallow's End, e salutami tanto il tuo piccolo amico malato! Spero che guarisca presto.", 0xe471aaf9, nil, 0x8c369374, 0xf9d6b077, 0x85f6bca9, ".m..." },
  [8371] = { "Sforzi congiunti", "Porta $N1 Alterac Valley Mark of Honor, $N2 Arathi Basin Mark of Honor e $N3 Warsong Gulch Mark of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", "Non combattiamo più battaglie isolate contro l'Orda, <ragazzo/ragazza>.\n\nUna vittoria su un fronte significa negare all'Orda risorse che userebbe contro di noi in un'altra battaglia. Allo stesso modo, perdere una qualsiasi battaglia potrebbe dare il vantaggio al nostro avversario da qualche altra parte del mondo.\n\nL'Alleanza ha bisogno di più combattenti con questa visione globale... veri veterani esperti! {name}, torna da me dopo aver combattuto contro l'Orda in tutti i nostri campi di battaglia attivi.", "Come vanno i tuoi viaggi, <ragazzo/ragazza>?", "Non sei tipo da deludere, {name}! Ciò che hai imparato va oltre medaglie ed encomi da quattro soldi. Ciò che hai imparato può venire solo dall'esperienza e dalla tempra forgiata sul campo di battaglia.\n\nHai fatto bene, {class}. Sei un vero eroe dell'Alleanza!", 0x3f0cde75, 0x65689054, 0xc60bec64, 0x8f1e0c1a, 0xe9fc3fdf, ".....", nil, nil, 0x678d2ae6, 0xbdf4388a, nil },
  [8372] = { "Combatti per la Warsong Gulch", "Porta $N1 Warsong Gulch Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", "Le Silverwing Sentinels sono in guerra con i Warsong Outriders per la distruzione che gli orchi stanno causando alla foresta. Ci sono però più ragioni per difendere proprio questa foresta che il semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende Ashenvale difendibile da un attacco su larga scala. Senza di essa, Astranaar durerebbe un giorno o due prima di essere annessa alle Barrens.\n\nFai la tua parte nella lotta contro i Warsong Outriders, {name}! Per l'Alleanza!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ben fatto, {name}! Hai servito bene l'Alleanza.", 0xbeadcb52, 0x5ca6c72a, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8373] = { "Il potere del pino", "Usa uno Stink Bomb Cleaner per rimuovere qualsiasi Forsaken Stink Bomb sganciata su Southshore. Quando hai finito, torna dal Sergeant Hartman, a Southshore.", "La cosa che odio di più dell'Hallow's End sono le bombe puzzolenti che i Forsaken usano su Southshore. Chi l'avrebbe detto che festeggiare la liberazione comportasse un pasticcio così puzzolente?\n\nDurante l'Hallow's End, usa questo detergente per rimuovere tutte le schifose bombe puzzolenti che l'Horde potrebbe sganciare qui al villaggio. Usa il potere del pino per combattere i cattivi odori.\n\nFa' la tua parte per tenere pulita Southshore e ti darò qualche dolcetto dell'Hallow's End che sono sicuro ti piacerà. Affare fatto?", "Quei maledetti Forsaken... è già abbastanza brutto che siano non morti, ma poi si scatenano e cominciano a creare guai nel mio villaggio, proprio il mio!", "Ah, qui intorno sembra già quasi profumare di più. Quasi.\n\nGrazie a te, {name}, Southshore potrebbe superare un altro Hallow's End. Ecco i tuoi dolcetti, con i miei ringraziamenti! Se finisci le caramelle, credo che a Ironforge ci sia una gnoma di nome Katrina Shimmerstar che può vendertene altre; credo che ci sia solo durante l'Hallow's End.", 0x6e6d4a39, 0x689dd20c, 0x33ac3eda, 0x6af39b38, 0xb45d1953, "....." },
  [8374] = { "Conquistare l'Arathi Basin", "Porta $N1 Arathi Basin Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", "Vincere una guerra non significa solo superare in astuzia e in combattimento l'avversario. Spesso la vittoria si riduce semplicemente a produrre più del nemico.\n\nNell'Arathi Basin c'è una scorta considerevole di risorse per la fazione che riuscirà a conquistarla per prima.\n\nSe vince l'Alleanza, ci saranno più spade e picche per le nostre truppe. Se vincesse l'Orda, quelle spade e picche verrebbero forgiate comunque, solo che sarebbero puntate contro di noi! Ora è il momento di aiutare l'Alleanza nell'Arathi Basin, {name}.", "Dimmi, che notizie dal fronte?", "Bel lavoro, soldato! Continua così e faremo correre l'Orda fino a Orgrimmar.", 0x637e1f39, 0x5e7275f8, 0x9452b6af, 0xa2aee952, 0x43526442, "....." },
  [8375] = { "Ricorda l'Alterac Valley!", "Porta $N1 Alterac Valley Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", "Non fraintendermi, {name}. L'Orda ha perfettamente ragione quando dice che l'Alterac Valley è territorio dei Frostwolf.\n\nVedi, la Stormpike Expedition arrivò nella zona come visitatrice pacifica, in cerca di minerali e reliquie. I Frostwolf reagirono con l'atto di aggressione più brutale e incivile che l'Alleanza abbia mai subito.\n\nNon dimentichiamo mai i valorosi nani periti in quel vile attacco a sorpresa. Va' ora, {class}, fai la tua parte nella battaglia per l'Alterac Valley. Per l'Alleanza!", "Che notizie porti, {name}?", "Hai fatto la tua parte, {name}. L'Alleanza non può lasciare senza risposta gli atti incivili dell'Orda!", 0xea2379c4, 0xcc86450b, 0x1106d7d2, 0x816d03be, 0x0945fff6, "....." },
  [8393] = { "Conquistare l'Arathi Basin", "Porta $N1 Arathi Basin Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", "Vincere una guerra non significa solo superare in astuzia e in combattimento l'avversario. Spesso la vittoria si riduce semplicemente a produrre più del nemico.\n\nNell'Arathi Basin c'è una scorta considerevole di risorse per la fazione che riuscirà a conquistarla per prima.\n\nSe vince l'Alleanza, ci saranno più spade e picche per le nostre truppe. Se vincesse l'Orda, quelle spade e picche verrebbero forgiate comunque, solo che sarebbero puntate contro di noi! Ora è il momento di aiutare l'Alleanza nell'Arathi Basin, {name}.", "Dimmi, che notizie dal fronte?", "Bel lavoro, soldato! Continua così e faremo correre l'Orda fino a Orgrimmar.", 0x637e1f39, 0x5e7275f8, 0x9452b6af, 0xa2aee952, 0x43526442, "....." },
