  [8401] = { "Combatti per la Warsong Gulch", "Porta $N1 Warsong Gulch Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", "Le Silverwing Sentinels sono in guerra con i Warsong Outriders per la distruzione che gli orchi stanno causando alla foresta. Ci sono però più ragioni per difendere proprio questa foresta della filosofia conservazionista che le Silverwing sostengono.\n\nLa foresta forma una barriera strategica che rende Ashenvale difendibile da un attacco su larga scala. Senza di essa, Astranaar durerebbe un giorno o due prima di essere annessa alle Barrens. Fai la tua parte nella lotta contro i Warsong Outriders! Per l'Alleanza!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Bel lavoro, {name}. Grazie a te le nostre difese naturali ad Ashenvale resteranno intatte per un altro giorno.", 0xbeadcb52, 0x5ca6c72a, 0x82248f89, 0x378bede6, 0x83c232b5, "....." },
  [8402] = { "Combatti per la Warsong Gulch", "Porta $N1 Warsong Gulch Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", "Le Silverwing Sentinels sono in guerra con i Warsong Outriders per la distruzione che gli orchi stanno causando alla foresta. Ci sono però più ragioni per difendere proprio questa foresta che il semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende Ashenvale difendibile da un attacco su larga scala. Senza di essa, Astranaar durerebbe un giorno o due prima di essere annessa alle Barrens.\n\nFai la tua parte nella lotta contro i Warsong Outriders, {name}! Per l'Alleanza!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ben fatto, {name}! Hai servito bene l'Alleanza.", 0xbeadcb52, 0x5ca6c72a, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8403] = { "Combatti per la Warsong Gulch", "Porta $N1 Warsong Gulch Marks of Honor a un Alliance Brigadier General fuori dai campi di battaglia.", "Le Silverwing Sentinels sono in guerra con i Warsong Outriders per la distruzione che gli orchi stanno causando alla foresta. Ci sono però più ragioni per difendere proprio questa foresta che il semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende Ashenvale difendibile da un attacco su larga scala. Senza di essa, Astranaar durerebbe un giorno o due prima di essere annessa alle Barrens.\n\nFai la tua parte nella lotta contro i Warsong Outriders, {name}! Per l'Alleanza!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ben fatto, {name}! Hai servito bene l'Alleanza.", 0xbeadcb52, 0x5ca6c72a, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8409] = { "Barili rovinati", "Torna dalla Darkcaller Yanka, al Wickerman Festival, nelle Tirisfal Glade.", "Le uova marce sono state messe con successo nel barile. Le prossime partite di birra della Southshore Inn saranno di sicuro rovinate!\n\nOra dovresti tornare dalla Darkcaller Yanka, al Wickerman Festival nelle Tirisfal Glade, e riferire il tuo successo.", nil, "Ah, successo! Hai dimostrato il vero spirito dell'Hallow's End... lo spirito dei Forsaken, dovrei dire!\n\n<La Darkcaller Yanka ride e si sfrega le mani.>\n\nGodo al pensiero che Southshore dovrà ora accontentarsi di birra cattiva o farne a meno! Quanto a te, prendi questi dolcetti. Credo che ne farai buon uso!", 0xcbae20af, 0xce9b33d2, 0xe895ed09, nil, 0xb14ac7c0, "...m." },
  [8411] = { "Padroneggiare gli elementi", "Porta gli elementi terra, aria, fuoco e acqua a Bath'rah the Windwatcher.", "Benvenuto, amico. Tu mi porti gli elementi e poi parliamo.", "Dove sono gli elementi, amico?", "Questi sono gli elementi che mi servono. Ora parliamo.", 0xc6de61cd, 0x53ec0188, 0xf3c3ef42, 0xc83605a1, 0xbf2f0684, "....." },
  [8412] = { "Il totem spirituale", "Porta i pezzi per il totem spirituale a Bath'rah the Windwatcher.", "Gli spiriti elementali di questo posto non mi vogliono più bene.\n\nTu sai dei totem più di chiunque altro, e io ho bisogno di un totem spirituale per proteggermi. Gli elementi li abbiamo già, ora ci serve qualcosa di più legato alla natura. Più primordiale.\n\nNelle Western Plaguelands puoi uccidere orsi per gli artigli e ragni per gli occhi. Gli uccelli spazzini mangiano di tutto, quindi potrebbero avere l'una o l'altra cosa.", "Gli spiriti sanno cosa stiamo facendo, e cercano di uccidermi! Spero che tu abbia i pezzi.", "Ottimo, amico! Proviamolo...", 0xb513abac, 0xfad1dd4d, 0xfa023a9f, 0xdcff1581, 0x4f7f69ce, "....." },
  [8413] = { "Il voodoo", "Porta le piume voodoo a Bath'rah the Windwatcher.", "Il totem spirituale non basta. Ci serve un po' di magia voodoo per farlo funzionare a dovere.\n\nI troll del tempio sommerso hanno piume piene di magia voodoo. Va' lì e uccidi Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Allora avremo abbastanza magia per un vero totem spirituale.", "Dove sono le piume, amico?", "Era ora che questo troll si facesse una bella notte di sonno! Il totem spirituale veglierà su di me.\n\nHo passato tanto tempo a collezionare cose, forse vuoi qualcosa per tutto il disturbo?", 0x44084925, 0x7d0d0c69, 0x438ab205, 0x4e430c1d, 0xccb3a8ea, "....." },
  [8415] = { nil, "Parla con il Commander Ashlam Valorfist, a Chillwind Point.", "Il Commander Ashlam Valorfist ha lanciato un appello per <un/una> <paladino/paladina> della tua purezza e del tuo valore, {name}. Lo troverai a Chillwind Point, nella parte meridionale delle Western Plaguelands. Cercalo e aiutalo nella sua causa per la Luce!", nil, "Molto bene, {class}! Vediamo di che pasta sei <fatto/fatta>.", nil, 0x68fa4270, 0x9b5889f4, nil, 0xb58b885c, "m..m." },
  [8419] = { "La richiesta di un imp", "Porta un pezzo di felcloth a Impsy, a Felwood.", "{name}, un imp di Felwood di nome Impsy ha chiesto la tua presenza. È piuttosto strano, perché ha chiesto che tu porti un pezzo di felcloth come segno di buona fede. Considerando il potere che già possiedi come <stregone/strega>, posso solo supporre che tu sappia che i satiri di Felwood portano questo felcloth.\n\nPuoi trovare Impsy appena a nord delle Bloodvenom Falls, che ho sentito dire sono piuttosto belle in questo periodo dell'anno.", "Hai il mio felcloth?", "Che splendore di {class} sei!\n\n<Impsy si porta il felcloth al viso.>\n\nOh, come adoro sentirlo, il modo in cui brucia la pelle e intreccia pensieri malvagi nella mente...", 0x8f923b54, 0xcaccde4e, 0xba1e506c, 0xe4cd415e, 0x051f42a7, "....." },
  [8420] = { nil, "Porta un pezzo di felcloth a Impsy, a Felwood.", nil, "Hai il mio felcloth?", nil, nil, 0xcaccde4e, nil, 0xe4cd415e, nil, "m.m.m" },
  [8423] = { "Fratellanza guerriera", "Uccidi $N1 Helboar nelle Blasted Lands e torna dal Fallen Hero of the Horde.", "<L'Eroe ti squadra.>\n\nSei un {class}, senza dubbio. Vorrei chiederti un compito onorevole, ma devo mettere alla prova la tua forza.\n\nSi dice che Rexxar misurasse l'affilatura delle sue lame uccidendo un helboar con un solo colpo rapido. Ora misurerò la tua forza facendoteli uccidere.", "Le spine ardenti degli helboar lasciano cicatrici orribili. Non temere il dolore e lo sfregio, guerriero: non sono nulla in confronto alla prigione a cui sono legato.", "Non mi serve una prova per sapere cosa hai fatto, {class}. Vedo la determinazione scolpita nella tua espressione.", 0xde7fa3a8, 0x31609ff6, 0x8f24b94b, 0x5be003e0, 0x2aacbdb4, "....." },
  [8424] = { "Guerra agli Shadowsworn", "Massacra gli Shadowsworn nelle Blasted Lands e torna dal Fallen Hero of the Horde.", "La continua presenza degli shadowsworn nelle Blasted Lands mi causa grande dolore. I loro rituali oscuri e i loro incantesimi provocano un'agonia che non ho mai provato da vivo.\n\nAttraverso di te posso consegnare il mio messaggio di dolore. Va' e porta la mia ira.", "Gli shadowsworn non si sconfiggono facilmente, vero? Ma sei un guerriero, e trionferai o perirai nel tentativo.", "Hai già placato il mio dolore e mi hai onorato. Grazie, {class}.", 0x7e21c995, 0xe2db1389, 0x7336323a, 0xdecd09a7, 0x41506fda, "....." },
  [8425] = { nil, "Porta le Voodoo Feathers dei troll del Sunken Temple al Fallen Hero of the Horde.", "Il tuo onore mi ha portato un po' di pace. È giusto che ti offra qualcosa in cambio.\n\nLe mie armi e la mia armatura erano splendide in vita, eppure ora non mi servono a nulla. Sarebbero più utili nelle tue mani.\n\nViaggia fino al tempio sommerso e distruggi i guardiani troll Gasher, Mijan, Zolo, Hukku, Zul'lor e Loro. Portano piume magiche che possono ricomporre il mio corpo fisico abbastanza a lungo da concederti una ricompensa.", "Sei già <tornato/tornata>? Il tempo per me non è più lo stesso; forse per te è stato davvero un lungo viaggio...", "Finalmente posso sentire di nuovo il freddo tocco dell'acciaio, anche solo per un momento.", nil, 0x4f5e1843, 0x400f79cc, 0x05e22a31, 0x1afd1e5f, "m...." },
  [8446] = { "Avvolto nell'incubo", "Trova qualcuno capace di decifrare il significato del Nightmare Engulfed Object.\n\nForse un druido di grande potere potrebbe aiutarti.", "La corruzione trasuda da questo oggetto.\n\nPotrebbe esserci un legame tra questo oggetto e i draghi che emergono dal Dream. Devi trovare qualcuno capace di decifrare il significato di questo oggetto. Forse i druidi di Moonglade o di Cenarion Hold potrebbero aiutarti.", "Sì, {race}?", "Devo rimuovere la contaminazione da questo oggetto. Potrebbe far luce sui miei recenti fallimenti nell'addentrarmi nel Dream. Dammelo.", 0x246a0099, 0x0ddca4a0, 0x26d51f90, 0x98b629a5, 0x648c4b7e, "....." },
  [8447] = { "Leggende che si risvegliano", "Attendi che il Keeper Remulos, a Moonglade, purifichi il Nightmare Engulfed Object.", "Le acque del Lake Elune'ara dovrebbero dissolvere gli incubi che avvolgono questo oggetto. Dammi un momento per compiere la purificazione, {name}.", nil, "Prendi il suo anello, {name}. Ha servito il suo scopo per Malfurion. Ora servirà un nuovo scopo per te...", 0x40aca492, 0x878b703d, 0x84513d69, nil, 0x9a9b424a, "...m." },
  [8492] = { "L'Alleanza ha bisogno di Copper Bars!", "Porta $N1 Copper Bars al Sergeant Stonebrow nel Military Ward di Ironforge.", "Ehi, {class}, sembri abbastanza in forma per contribuire allo sforzo bellico! Ci serve tutto l'aiuto possibile per mettere insieme il materiale necessario alla guerra di Ahn'Qiraj, ed è il tuo giorno fortunato.\n\nRaccolgo lingotti di rame in pile da venti. È per una buona causa, che ne dici? Pensi di poter aiutare l'Alleanza?", "Hai raccolto quei venti lingotti di rame, soldato?", "Ce l'hai fatta, <ragazzo/ragazza>! Metteremo subito questi lingotti di rame sulla pila e li useremo per produrre il materiale bellico. Sono gli sforzi di persone come te che mi rendono orgoglioso di servire l'Alleanza. Bel lavoro, soldato!\n\nE se ti capita di trovare altri lingotti di rame, assicurati che arrivino a me.", 0x757406f0, 0x6237b7e8, 0x51825aa9, 0xdcd7c22d, 0x4a7e2fe9, ".....", nil, nil, nil, nil, 0x90199bdf },
  [8494] = { "L'Alleanza ha bisogno di Iron Bars!", "Porta $N1 Iron Bars al Corporal Carnes nel Military Ward di Ironforge.", "Ma salve, <signor/signora> elegantone, che piacere vederti. Nel caso non l'avessi sentito mentre eri là fuori ad \"avventurarti\", l'Alleanza si sta preparando a una guerra ad Ahn'Qiraj e ha bisogno di lingotti di ferro... un mucchio. Portameli in pile da venti. Possiamo contare su di te, vero, {class}?", "Se hai quei venti lingotti di ferro, non voglio sapere dove li tieni nascosti!", "Bene, bene, ma guarda chi c'è: {name}. E ce l'hai fatta. Immagino che ora dovrò tenerti d'occhio. Mi costa dirlo, ma grazie per i tuoi sforzi. L'Alleanza non dimenticherà, e nemmeno io. Ora torna là fuori a sgobbare per qualunque altra cosa ci sia da raccogliere.", 0x9fa1d26b, 0xbe9c435f, 0xe062b09f, 0x77c47230, 0x4adb19d0, ".....", nil, nil, 0x4c0ca3d6, nil, nil },
  [8499] = { nil, nil, nil, "Oh, una spedizione da mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", nil, nil, nil, nil, 0x89b01d8f, nil, "mmm.m" },
  [8503] = { "L'Alleanza ha bisogno di Stranglekelp!", "Porta $N1 Stranglekelp al Private Draxlegauge nel Military Ward di Ironforge.", "Allora, {class}, ti ho già parlato di tutti i favolosi usi dello stranglekelp? Sì? Oh be'... in ogni caso ce ne serve tanto, e quando dico tanto, intendo tantissimo! Pensi di poterci aiutare? So che significa rinunciare a tutte le cose meravigliose che puoi crearci, ma è per una buona causa!", "È falso! Io non sottrarrei mai dello stranglekelp dalle pile qui. Anche se si potrebbe esserne tentati, visto che è praticamente una panacea di utilità pratica. *coff* non avresti per caso lo stranglekelp di cui parlavamo prima?", "Evviva! Altri venti fatti. Sei il migliore. Suppongo che dovrei impacchettare tutto prima che appassisca. Così tanto stranglekelp, così poco tempo!\n\nGrazie ancora, {class}!", 0x63f519e9, 0x6f3dcf85, 0x986b25d7, 0x72242e7d, 0xc0116e1a, "....." },
  [8505] = { "L'Alleanza ha bisogno di Purple Lotus!", "Porta $N1 Purple Lotus al Master Nightsong nel Military Ward di Ironforge.", "{class}, il loto viola è un fiore dai molteplici usi. Sono qui su richiesta dell'Alleanza come esperto di queste applicazioni, per conservare le erbe raccolte e per garantire che lo sforzo bellico ottenga abbastanza loto viola per qualunque funzione abbiano in mente.\n\nVorrei che tu andassi per il mondo e tornassi da me con alcuni di questi fiori. È qualcosa che puoi fare?", "Hai le erbe di loto viola che ti ho chiesto?", "Il tuo contributo è molto apprezzato, {class}. Solo con gli sforzi congiunti di tutti riusciremo a respingere l'avanzata spietata dei silitidi e di qualunque forza li stia spingendo. Persino l'Orda sta ammassando la propria scorta di loto viola. Se ne trovi altro, ti prego, torna da me qui.", 0x96884544, 0x1bfe9765, 0xc21d38b7, 0x46a461af, 0x5dc529c8, "....." },
  [8509] = { "L'Alleanza ha bisogno di Arthas' Tears!", "Porta $N1 Arthas' Tears al Sergeant Major Germaine nel Military Ward di Ironforge.", "Sarò breve e diretto, {class}. L'Alleanza deve raccogliere una grande quantità di Arthas' Tears per lo sforzo bellico di Ahn'Qiraj. Non chiedermi a cosa servano: eseguo solo gli ordini. Ma vorrei che tu raccogliessi quante più di queste erbe possibile e me le riportassi qui. Sei disposto a farlo?", "Cosa? Parla più forte, {class}! Hai quel carico di Arthas' Tears che ti ho chiesto?", "Bel lavoro, {class}. Devo dire che sono piacevolmente sorpreso. Non crederesti a quante persone sono passate offrendosi di aiutare, senza mai tornare. Lascia che le metta in una cassa e le registri a tuo nome, poi potremo riparlare di quante altre di queste piante mi servono.", 0x6d6dd93b, 0x57f7aa6f, 0x60fc0f60, 0x3c0166a7, 0xf3dfc769, "....." },
  [8511] = { "L'Alleanza ha bisogno di Light Leather!", "Porta $N1 Light Leather a Bonnie Stoneflayer nel Military Ward di Ironforge.", "Noi Stoneflayer abbiamo una lunga tradizione di scuoiatori, {class}. Per questo l'Alleanza ha chiesto alla mia famiglia di aiutare a raccogliere cuoio leggero per lo sforzo bellico di Ahn'Qiraj. Sono qui per assicurarmi che il cuoio venga conciato correttamente, qualunque sia l'uso che vogliono farne. Ma ci serve il tuo aiuto.\n\nVisto che devo restare qui a fare questo, mi serve che tu vada a raccogliere le pelli e me le riporti qui. Che ne dici, <ragazzo/ragazza>, ci provi?", "{class}, spero proprio che sia il cuoio leggero che mi hai promesso.", "Oserei dire che l'Alleanza sarà molto contenta di queste pelli, {class}. Mi assicurerò che nemmeno una vada sprecata. Grazie, e torna a trovarmi quando le avrò contate per vedere se ne servono altre.", 0x166b0989, 0x25b32673, 0x9167564a, 0xbc6f644c, 0x2612f9b9, ".....", nil, nil, 0x7b43942b, nil, nil },
  [8513] = { "L'Alleanza ha bisogno di Medium Leather!", "Porta $N1 Medium Leather al Private Porter nel Military Ward di Ironforge.", "Sì, <signore/signora>, mi è stato affidato il compito di raccogliere e registrare tutto il cuoio medio raccolto per lo sforzo bellico. Se hai i mezzi per procurarti cuoio medio, da qualunque fonte, ti prego di portarmelo qui. Apprezzerei davvero una mano, se hai tempo.", "Sì, <signore/signora>, mi ricordo di te. È il cuoio medio quello che hai con te?", "Wow! Mi sembra che tu fossi qui solo un attimo fa a offrirti <volontario/volontaria>. Grazie mille per la donazione. Lo impacchetto e lo conto subito. Sai proprio come rallegrare la giornata a uno.", 0xfb782e71, 0xad64ad92, 0x5b621688, 0xd58c253b, 0x12b794b1, ".....", nil, nil, 0x6ff18d34, 0x965b27ea, nil },
  [8515] = { "L'Alleanza ha bisogno di Thick Leather!", "Porta $N1 Thick Leather a Marta Finespindle nel Military Ward di Ironforge.", "Oh, sarà fantastico! {class}, lo sforzo bellico di Ahn'Qiraj è in pieno svolgimento, e mi hanno messo a capo della registrazione di tutto il cuoio spesso che arriva. Ci faremo un sacco di cose, ma prima dobbiamo procurarcene un sacco. E intendo letteralmente una tonnellata! Ed è qui che entri in gioco tu.\n\nAllora, pensi di poter andare là fuori e riportarmi una bella pila grossa di cuoio spesso? Eh, eh?!", "È cuoio spesso quello che hai nello zaino, {class}? Lo è? Non vedo l'ora che me lo consegni! Saranno tutti così contenti di noi, non credi?", "Oh, sapevo che ce l'avresti fatta, {class}, lo sapevo! Lo farò arrivare nelle mani giuste il prima possibile. Ora, vediamo un po'. Uhm, sembra che il nostro conteggio stia procedendo piuttosto bene. Ripassa da me tra un attimo, quando avrò finito di contare, per vedere se ne serve altro. Perché se ne serve, sei tu che voglio là fuori a raccoglierlo per me!", 0x460fae65, 0x808cb123, 0x9a42642a, 0x83fccb86, 0xc7cd8ddd, "....." },
  [8517] = { "L'Alleanza ha bisogno di Linen Bandages!", "Porta $N1 Linen Bandages alla Sentinel Silversky nel Military Ward di Ironforge.", "La guerra di Ahn'Qiraj sarà lunga e sanguinosa. L'Alleanza fa una cosa molto saggia chiedendo l'aiuto di te e di quelli come te per accumulare il materiale necessario prima di gettarsi a capofitto nel conflitto.\n\nMi è stato chiesto di dirigere la raccolta di bende di lino per la guerra, e spero che mi aiuterai ad ammassarne quante ne servono. Non è una cosa da poco, ma almeno le bende di lino sono le meno difficili da creare. Sei con noi, {class}?", "Hai le venti bende di lino che mi servono, {class}?", "Molti sono i soldati che trarranno beneficio dal tuo contributo di oggi, {class}. Mi occuperò di persona di far conoscere all'Alleanza i tuoi sforzi. Concedimi un momento per riporre queste bende come si deve e aggiornare il conteggio, poi ripassa da me per vedere se me ne servono altre.\n\nChe la Luce di Elune risplenda su di te, {race}!", 0x39ccd76b, 0xb6425974, 0x33421156, 0xd06208b4, 0x57d65781, "....." },
  [8520] = { "L'Alleanza ha bisogno di Silk Bandages!", "Porta $N1 Silk Bandages alla Nurse Stonefield nel Military Ward di Ironforge.", "Con la guerra di Ahn'Qiraj alle porte dobbiamo fare tutto il possibile perché i nostri soldati abbiano tutto ciò di cui hanno bisogno. Ed è proprio quello che facciamo qui. Per quanto mi riguarda, mi è stato affidato il compito di assicurarmi che raccogliamo abbastanza bende di seta.\n\nPensi di potermi aiutare, {class}?", "Salve, {class}, sei <riuscito/riuscita> a procurarti quelle venti bende di seta?", "{class}, ce l'hai fatta! Grazie a te siamo un altro passo più vicini al nostro obiettivo con le bende di seta. Le metto via, e poi possiamo parlare ancora, se ti va.", 0x15d829cb, 0x02f534a1, 0xc152ec92, 0xfc304e96, 0xdb5433ca, "....." },
  [8522] = { "L'Alleanza ha bisogno di Runecloth Bandages!", "Porta $N1 Runecloth Bandages al Keeper Moonshade nel Military Ward di Ironforge.", "Discuti pure dei meriti della guerra, se vuoi, {class}, ma ormai è stata messa in moto. Guarda la tua famiglia e i tuoi amici, e poi chiediti cosa puoi fare perché, se ne verranno coinvolti, abbiano ogni vantaggio per sopravvivere all'incendio.\n\nA tal fine raccolgo qui bende di runestoffa, da qualunque fonte. Vuoi fare una donazione?", "I giorni passano uno dopo l'altro, e noi andiamo avanti. {class}, hai quelle bende di runestoffa?", "Sei da lodare, {class}, per la tua perseveranza in questo compito. Metterò via queste bende, e poi vorrei parlarti di nuovo della possibilità di raccoglierne altre.", 0xf93887af, 0xae5b1001, 0x62a11c22, 0xde0bf237, 0x5557e41f, "....." },
  [8524] = { "L'Alleanza ha bisogno di Rainbow Fin Albacore!", "Porta $N1 Rainbow Fin Albacore a Slicky Gastronome nel Military Ward di Ironforge.", "Ehi, amico! Se ti dicessi: \"Non pensi che i soldati debbano avere cibo da mangiare come chiunque altro?\", tu ovviamente risponderesti \"sì\". Sono d'accordo con te al 110%! Sono contento che siamo d'accordo. Tutto ciò che devi fare è andare là fuori, pescare un bel po' di rainbow fin albacore crudo, poi cucinarlo tutto e riportarmelo qui. Mmm, mmm, ne sento già il sapore.", "Scommetto che sei <tornato/tornata> con tutto il rainbow fin albacore di cui parlavamo prima, vero, {class}?", "Due per l'Alleanza, uno per me, due per l'Alleanza, uno per me. Ehi, pescivendolo, ottimo lavoro. Vedo che farai onore al club. Mi sembra però che ci serva altro albacore. Perché non vai là fuori a rimediarne un altro po'? Sento già brontolare lo stomaco.", 0x5b42adcf, 0x3c1790bd, 0x09512125, 0xb86def6c, 0xda8db929, "....." },
  [8526] = { "L'Alleanza ha bisogno di Roast Raptor!", "Porta $N1 Roast Raptor a Sarah Sadwhistle nel Military Ward di Ironforge.", "Oh, come va, {class}? Vedo che ti interessa magari raccogliere cibo per la guerra imminente di Ahn'Qiraj? Chissà come, mio padre ha pensato che sarebbe stata un'esperienza educativa per me offrirmi volontaria qui. Grosso errore. Non mi piace nemmeno mangiare carne.\n\nComunque, se ti va, potresti portarmi un sacco di roast raptor. A quanto pare è quello che vorranno tutti i soldati.", "Allora, hai tutto quel roast raptor?", "Accidenti, che bello. Grazie per avermi portato tutta questa carne animale bruciata, {class}. La metto sul mucchio laggiù. Sono sicura che qualcuno se ne occuperà. Immagino che, se hai tempo libero, potresti portarmene ancora?", 0x098b1abf, 0xc0048d2b, 0xe72e6f63, 0x4407bf0f, 0x69244cc0, "....." },
  [8528] = { "L'Alleanza ha bisogno di Spotted Yellowtail!", "Porta $N1 Spotted Yellowtail alla Huntress Swiftriver nel Military Ward di Ironforge.", "Raccogliere pesce cotto potrà non sembrare eroico, ma non sottovalutare il valore della preparazione, giovane {class}. I soldati devono mangiare come chiunque altro, e noi siamo qui per fare la nostra parte perché abbiano ciò che serve quando comincerà la guerra di Ahn'Qiraj.\n\nPerciò sto accumulando spotted yellowtail, una fonte di nutrimento versatile che si conserva bene e si può usare in molti piatti diversi. E non ha nemmeno l'odore di certi altri pesci d'acqua salata. Sei disposto ad aiutarmi in questa impresa?", "Confido che tu sia <tornato/tornata> così presto con lo spotted yellowtail di cui abbiamo parlato.", "Grazie per questo dono, {class}, e con tanto tempismo. Ai nostri soldati di certo non mancherà qualcosa da mangiare. Lascia solo che riponga questi pesci come si deve, e poi io e te possiamo parlare di un secondo carico, se sei disposto.", 0x7294f481, 0x9bbd3662, 0x271c6dcb, 0x7b69ba9d, 0x0e1fc6c8, "....." },
  [8565] = { "Vittorie passate ad Arathi", nil, nil, nil, "Ah, sì! Certo che non dimenticheremmo i tuoi successi passati nell'Arathi Basin.", 0x1b6fa606, nil, nil, nil, 0x84b7e476, ".mmm." },
  [8566] = { "Vittorie passate ad Arathi", nil, nil, nil, "Ah, sì! Certo che non dimenticheremmo i tuoi successi passati nell'Arathi Basin.", 0x1b6fa606, nil, nil, nil, 0x84b7e476, ".mmm." },
