  [8844] = { "Un Commendation Signet", nil, nil, nil, "Molto bene: le tue azioni sono state registrate, e ti viene riconosciuto il merito dei tuoi sforzi. Continua così, {class}.\n\nSe hai altri sigilli da consegnare, posso aiutarti anche con quelli.", 0x34f5a7be, nil, nil, nil, 0x3fd3f6f6, ".mmm." },
  [8845] = { "Dieci Commendation Signets", nil, nil, nil, "Eccellente! Non è un sacrificio da poco quello che hai fatto per guadagnarti questi sigilli, e il tuo servizio sarà riconosciuto come si deve. Sono gli avventurieri come te, {name}, a fare davvero la differenza.\n\nFammi sapere se hai altri sigilli da consegnare; ti aiuterò volentieri con tutti quelli che vuoi cambiare.", 0xc9ab59cb, nil, nil, nil, 0xd1519e98, ".mmm." },
  [8846] = { "Cinque sigilli per i rifornimenti di guerra", nil, nil, "Ah, sei qui per altri rifornimenti per te, eh? Be', capisco di certo il bisogno di altro materiale... basta guardarsi intorno per averne la prova.\n\nTi darò altri rifornimenti, ma dovrai darmi in cambio un numero adeguato di sigilli di encomio. Non riceverai alcun riconoscimento consegnando i sigilli in questo modo, ma potresti trovare qualcosa di utile per restare in vita quando la battaglia sarà finalmente arrivata.", "Bene, allora è deciso: ecco i tuoi rifornimenti, {class}. Se vuoi fare un altro scambio, sono pronto ad autorizzarlo. Basta che tu me lo dica e lo farò.\n\nContinua così, {name}. Ci serve tutto il materiale che riusciamo a raccogliere se vogliamo vincere. Se ognuno fa la sua parte, la vittoria sarà nostra!", 0x87ab84fa, nil, nil, 0x44b98cd5, 0xb2839001, ".mm.." },
