  [8922] = { "Un congegno soprannaturale", "Porta il Sealed Blood Container a Mux Manascrambler, dentro Gadgetzan, a Tanaris.", "Devo trovare un modo per parlare con Anthion Harmon... o più precisamente, con il suo fantasma!\n\nConosco un ingegnere con uno strano interesse per il soprannaturale. Sostiene di poter costruire una macchina che gli permette di parlare con i morti!\n\nIl sangue che hai raccolto era destinato a lui: va' a Gadgetzan e portaglielo come pagamento per i suoi servigi!", "Hai qualcosa per me?", "Eccellente! Proprio mentre stavo finendo le scorte!\n\nDici che ti manda Deliana?", 0x412537f1, 0xedba7f2d, 0x51fbab6c, 0x25136523, 0x1185e9c7, "....." },
  [8923] = { "Un congegno soprannaturale", nil, nil, nil, nil, 0x412537f1, nil, nil, nil, nil, ".mmmm" },
  [8926] = { "Un giusto compenso", "Porta una Wildheart Belt e un set di Wildheart Gloves a Deliana, a Ironforge.", "Hai mantenuto la parola e portato il congegno costruito da Mux. Credo che sia doverosa una ricompensa, se voglio che tu continui a interessarti a salvarmi la pelle. Portami la cintura e il set di guanti che vuoi migliorare. Ti prometto che quelli che ti darò in cambio saranno di gran lunga superiori.", "Sei <pronto/pronta> a fare lo scambio?", "Tu hai rispettato la tua parte dell'accordo, io rispetterò la mia.\n\nRicorda solo che tengo per me i pezzi migliori finché il tuo lavoro non sarà finito.", 0x467758ec, 0xaf7ff1c4, 0xce2da401, 0x6608fbe7, 0x86434e09, "....." },
  [8927] = { "Un giusto compenso", nil, nil, nil, nil, 0x467758ec, nil, nil, nil, nil, ".mmmm" },
  [8929] = { "In cerca di Anthion", "Usa l'Extra-Dimensional Ghost Revealer all'ingresso di Stratholme e parla con il fantasma di Anthion Harmon.", "Be', non ci resta che provare l'invenzione del goblin. Si dice che Anthion sia stato falciato dalle legioni di non morti di Stratholme mentre cercava di varcarne i cancelli.\n\nProva a usare il congegno lì e scopri tutto ciò che sapeva Anthion.", nil, "Deliana ti ha detto di contattarmi? Farò del mio meglio per aiutarti, ma prima devo chiederti un grande favore.", 0xfd59b646, 0x1041fc47, 0x9d147007, nil, 0xa296c55d, "...m." },
  [8930] = { "In cerca di Anthion", "Usa l'Extra-Dimensional Ghost Revealer all'ingresso di Stratholme e parla con il fantasma di Anthion Harmon.", nil, nil, nil, 0xfd59b646, 0x1041fc47, nil, nil, nil, "..mmm" },
