  [8960] = { "Lo sfortunato destino di Bodley", "Viaggia fino alla Blackrock Mountain e usa l'Extra-Dimensional Ghost Revealer per trovare Bodley vicino alla Blackrock Spire.", "Quindi dobbiamo recuperare il resto del medaglione? Trovare Bodley sarà un bel grattacapo. È tornato alla Blackrock Mountain per tentare di rientrare nella Blackrock Spire e non è più tornato.\n\nTi consiglio di portare con te il congegno rivelatore di fantasmi del goblin, perché temo che sia successo il peggio.", nil, "Sono così contento che tu possa vedermi. Finalmente qualcuno con cui parlare!\n\nCi aiuterai, {name}? Aiuterai a rimediare al torto che abbiamo commesso e a rimettere le cose a posto? Se è vero che hai già il Top Piece of Lord Valthalak's Amulet, credo di poterti indicare la strada per ottenere le altre due parti, riunirle e mettere fine a tutto questo.\n\nOh, a proposito, ciao, mi chiamo Bodley. Piacere di conoscerti!", 0x87a6a36a, 0x180c9e9b, 0x8261f568, nil, 0xe7724fe3, "...m." },
  [8982] = { "Rintracciare la fonte", nil, nil, nil, nil, 0xc4ef4d74, nil, nil, nil, nil, ".mmmm" },
  [8983] = { "Rintracciare la fonte", nil, nil, nil, nil, 0xc4ef4d74, nil, nil, nil, nil, ".mmmm" },
  [8984] = { "La fonte svelata", nil, nil, nil, "Sì, ho creato io quelle fragranze. Un profumo meraviglioso, vero? Irresistibile.\n\nUna volta che i guerrieri dell'Alliance e dell'Horde saranno presi da questi sentimenti d'amore, non avranno la forza di fermare l'ascesa dello Shadow Council.\n\nSaranno indeboliti, impreparati. Preoccupandosi per i loro cari, perderanno il loro vantaggio.\n\nLa soluzione era così semplice. Perché ci ho messo tanto a trovarla? La debolezza di tutti passa per il cuore. E non c'è nulla che tu possa fare per fermare l'inevitabile.", 0xf2e77961, nil, nil, nil, 0x904005d0, ".mmm." },
  [8999] = { "Il meglio alla fine", "Consegna a Deliana il tuo Wildheart Cowl e la tua Wildheart Vest.", "È una storia straordinaria, {name}! Hai i miei ringraziamenti, e la gratitudine sincera di tutti coloro che vi sono stati coinvolti. Ora forse riuscirò a dormire la notte con tutti e due gli occhi chiusi.\n\nQuanto alla tua ricompensa, credo di avere alcune cose che ti piaceranno davvero.", "Come da accordi, sei <pronto/pronta> a consegnare i tuoi pezzi Wildheart in cambio dei nuovi Feralheart Cowl e Vest?", "Mi mancherai, {name}. Ti devo una tale gratitudine che credo non riuscirò mai a ripagarla.\n\nSpero che la tua nuova armatura per testa e torso ti piaccia, e che ti protegga a lungo.", 0x48402900, 0xd8200b75, 0x03db6ed6, 0x7a344d64, 0x2cf1dd7a, "....." },
})
